let myCanvas;
let currentAlgorithmIndex = -1;
let algorithms = [];
let paramsHistory = [];
let currentParamIndex = -1;

let zoomFactor = 1.0;
let panX = 0.0;
let panY = 0.0;
let probSetIndex = 0;
let paramArray = [0,0,0];
let colorPaletteIndex = 0;
const buttonLabels = [
  "New Algorithm","New Params","Prev Alg","Prev Params","Capture",
  "Prob Set","ColorPerm","Warp/Invert","Zoom +","Zoom -",
  "Pan Up","Pan Down","Pan Left","Pan Right"
];

let aaEnabled = true;
let aaLevel = 2;
const MAX_PIXEL_DENSITY = 4;

let uiContainer, uiHeader, uiContent;
let aaCheckbox, aaLevelDropdown;
let isDragging = false;
let dragOffsetX = 0;
let dragOffsetY = 0;

let upPressed = false;
let downPressed = false;
let leftPressed = false;
let rightPressed = false;
let panVelX = 0;
let panVelY = 0;
const PAN_ACCEL = 2.0;
const PAN_DAMP = 0.8;
const MAX_DEPTH = 40; 

let fractalMode = 0;
let fractalMode2 = 0;

function setup() {
  pixelDensity(1);
  initCanvas();
  newAlgorithm();
  newParameters();
  createUI();
}

function initCanvas() {
  if (myCanvas) myCanvas.remove();
  if (aaEnabled) {
    aaLevel = constrain(aaLevel, 1, MAX_PIXEL_DENSITY);
    pixelDensity(aaLevel);
  } else {
    aaLevel = 1;
    pixelDensity(1);
  }
  myCanvas = createCanvas(windowWidth, windowHeight, WEBGL);
  noStroke();

  for (let i = 0; i < algorithms.length; i++) {
    let fragSource = algorithms[i].fragSource;
    let vertCode = `
      attribute vec3 aPosition;
      void main(){
        gl_Position = vec4(aPosition,1.0);
      }
    `;
    let s = createShader(vertCode, fragSource);
    algorithms[i].shaderObj = s;
  }
}

function draw() {
  if (upPressed) panVelY -= PAN_ACCEL;
  if (downPressed) panVelY += PAN_ACCEL;
  if (leftPressed) panVelX += PAN_ACCEL;
  if (rightPressed) panVelX -= PAN_ACCEL;

  panX += panVelX;
  panY += panVelY;
  panVelX *= PAN_DAMP;
  panVelY *= PAN_DAMP;

  background(0);
  let algo = algorithms[currentAlgorithmIndex];
  if (algo && algo.shaderObj) {
    shader(algo.shaderObj);
    setUniforms(algo.shaderObj);
    beginShape(TRIANGLES);
    vertex(-1, -1, 0, 0, 0);
    vertex(1, -1, 0, 1, 0);
    vertex(1, 1, 0, 1, 1);
    vertex(-1, -1, 0, 0, 0);
    vertex(1, 1, 0, 1, 1);
    vertex(-1, 1, 0, 0, 1);
    endShape();
    resetShader();
  }
}

function windowResized(){
  initCanvas();
}

function mouseDragged(){
  if(isDragging){
    uiContainer.position((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - dragOffsetX, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - dragOffsetY);
  }
}

function mouseReleased(){
  isDragging = false;
}

function startDrag() {
  isDragging = true;
  let pos = uiContainer.position();
  dragOffsetX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - pos.x;
  dragOffsetY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - pos.y;
}

function endDrag(){
  isDragging = false;
}

function mouseWheel(event) {
  if (event.delta < 0) {
    doZoom(1.05, width/2, height/2);
  } else {
    doZoom(1.0/1.05, width/2, height/2);
  }
  return false;
}

function doZoom(scale, anchorX, anchorY) {
  let oldZ = zoomFactor;
  let newZ = oldZ * scale;
  let oldPX = panX;
  let oldPY = panY;
  panX = (oldZ * oldPX + (anchorX - width/2) * (newZ - oldZ)) / newZ;
  panY = (oldZ * oldPY + (anchorY - height/2) * (newZ - oldZ)) / newZ;
  zoomFactor = newZ;
}

function keyPressed() {
  if (key === 'N' || key === 'n') {
    handleButton("New Algorithm");
  } else if (key === 'M' || key === 'm') {
    handleButton("New Params");
  } else if (key === 'C' || key === 'c') {
    handleButton("Capture");
  }

  if (keyCode === LEFT_ARROW) leftPressed = true;
  if (keyCode === RIGHT_ARROW) rightPressed = true;
  if (keyCode === UP_ARROW) upPressed = true;
  if (keyCode === DOWN_ARROW) downPressed = true;
}

function keyReleased() {
  if (keyCode === LEFT_ARROW) leftPressed = false;
  if (keyCode === RIGHT_ARROW) rightPressed = false;
  if (keyCode === UP_ARROW) upPressed = false;
  if (keyCode === DOWN_ARROW) downPressed = false;
}

function newAlgorithm(){
  currentAlgorithmIndex++;
  algorithms.splice(currentAlgorithmIndex);
  let nodeCount = floor(random(40, 150));
  let fragCode = buildFragCode(nodeCount);
  var vertCode = `
    attribute vec3 aPosition;
    void main(){
      gl_Position = vec4(aPosition,1.0);
    }
  `;
  var s = createShader(vertCode, fragCode);
  algorithms.push({fragSource:fragCode, shaderObj:s});
  currentParamIndex = -1;
  paramsHistory = [];
}

function newParameters(){
  if(currentAlgorithmIndex < 0) return;
  currentParamIndex++;
  paramsHistory.splice(currentParamIndex);
  paramsHistory.push([random(1), random(1), random(1)]);
  fractalMode = floor(random(18));
  fractalMode2 = floor(random(18));
  colorPaletteIndex = floor(random(4));
}

function prevAlgorithm(){
  if(currentAlgorithmIndex>0) currentAlgorithmIndex--;
}

function prevParams(){
  if(currentParamIndex>0) currentParamIndex--;
}

function getCurrentParams(){
  if(currentParamIndex<0 || currentParamIndex>=paramsHistory.length) return [0,0,0];
  return paramsHistory[currentParamIndex];
}

function handleButton(label){
  switch(label){
    case "New Algorithm":
      newAlgorithm();
      newParameters();
      break;
    case "New Params":
      newParameters();
      break;
    case "Prev Alg":
      prevAlgorithm();
      break;
    case "Prev Params":
      prevParams();
      break;
    case "Capture":
      saveCanvas("capture_" + nf(millis(),1,0), "png");
      break;
    case "Prob Set":
      probSetIndex = (probSetIndex + 1) % 3;
      break;
    case "ColorPerm":
      applyColorPermutation();
      break;
    case "Warp/Invert":
      applyWarpOrInvert();
      break;
    case "Zoom +":
      doZoom(1.1, width/2, height/2);
      break;
    case "Zoom -":
      doZoom(1.0/1.1, width/2, height/2);
      break;
    case "Pan Up":
      panY -= 40;
      break;
    case "Pan Down":
      panY += 40;
      break;
    case "Pan Left":
      panX -= 40;
      break;
    case "Pan Right":
      panX += 40;
      break;
  }
}

function handleAAChange() {
  aaEnabled = aaCheckbox.checked();
  if (aaEnabled) {
    aaLevelDropdown.removeAttribute('disabled');
    let selectedVal = aaLevelDropdown.value();
    aaLevel = parseInt(selectedVal);
    aaLevel = constrain(aaLevel, 1, MAX_PIXEL_DENSITY);
  } else {
    aaLevelDropdown.attribute('disabled', '');
    aaLevel = 1;
  }
  initCanvas();
}

function applyColorPermutation(){
  var algo = algorithms[currentAlgorithmIndex];
  if(!algo) return;
  let newFrag = algo.fragSource.replace(
    "gl_FragColor = vec4(finalColor, 1.0);",
    "gl_FragColor = vec4(finalColor.gbr, 1.0);"
  );
  let vtx = `
    attribute vec3 aPosition;
    void main(){ gl_Position = vec4(aPosition,1.0); }
  `;
  var s = createShader(vtx, newFrag);
  algo.shaderObj = s;
  algo.fragSource = newFrag;
}

function applyWarpOrInvert(){
  var algo = algorithms[currentAlgorithmIndex];
  if(!algo)return;
  let r = random();
  let replacement = (r<0.5)
    ? "finalColor = 1.0 - finalColor;"
    : "finalColor = fract(finalColor + 0.5);";
  var newFrag = algo.fragSource.replace(
    "//POSTPROCESS_PLACEHOLDER",
    replacement + " //POSTPROCESS_PLACEHOLDER"
  );
  var vtx = `
    attribute vec3 aPosition;
    void main(){ gl_Position = vec4(aPosition,1.0); }
  `;
  var s = createShader(vtx, newFrag);
  algo.shaderObj = s;
  algo.fragSource = newFrag;
}

function buildFragCode(nodeCount){
  let eR = buildExpression(nodeCount,0);
  let eG = buildExpression(nodeCount,0);
  let eB = buildExpression(nodeCount,0);

  let fractalSnippet = buildFractalSnippet();
  let coordTransforms = buildCoordTransformSnippet();

  return `
#ifdef GL_ES
precision highp float;
#endif

uniform vec2 u_resolution;
uniform float u_zoom;
uniform vec2 u_pan;
uniform float u_time;
uniform float u_params[3];
uniform float u_fractalMode;
uniform float u_fractalMode2;
uniform float u_paletteIndex;

float safeDiv(float a, float b){
  return (abs(b) < 1e-6) ? 0.0 : (a/b);
}
float fold01(float v){
  v = abs(mod(v, 2.0));
  if(v > 1.0) v = 2.0 - v;
  return v;
}
float hash12(vec2 p) {
  vec3 p3  = fract(vec3(p.x, p.y, p.x) * 0.1031);
  p3 += dot(p3, p3.yzx + 19.19);
  return fract((p3.x + p3.y) * p3.z);
}
vec2 hash2(vec2 p){
  float n = sin(dot(p, vec2(7.0,157.0)));
  return fract(vec2(2097152.0,262144.0)*n);
}
float noise2D(vec2 p){
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash12(i + vec2(0.0,0.0));
  float b = hash12(i + vec2(1.0,0.0));
  float c = hash12(i + vec2(0.0,1.0));
  float d = hash12(i + vec2(1.0,1.0));
  vec2 u = f*f*(3.0-2.0*f);
  return mix(a, b, u.x) +
         (c - a)* u.y * (1.0 - u.x) +
         (d - b)* u.x * u.y;
}
vec2 swirlCoord(vec2 uv, float amount){
  float r = length(uv);
  float theta = atan(uv.y, uv.x);
  theta += amount * r;
  return vec2(r*cos(theta), r*sin(theta));
}
vec2 kaleidoCoord(vec2 z, float segCount){
  float r = length(z);
  float ang = atan(z.y, z.x);
  float seg = 6.28318530718 / segCount;
  ang = mod(ang, seg);
  return vec2(r*cos(ang), r*sin(ang));
}
vec2 moebiusCoord(vec2 z, float a){
  float denom = 1.0 + a*(z.x + z.y);
  if(abs(denom)<1e-4) denom = 1e-4;
  return z / denom;
}
vec2 invertCoord(vec2 z){
  float r2 = dot(z,z);
  if(r2 < 1e-6) r2 = 1e-6;
  return z / r2;
}

float hue2rgb(float f1, float f2, float h){
  if(h < 0.0) h += 1.0;
  if(h > 1.0) h -= 1.0;
  float c;
  if((6.0 * h) < 1.0) {
    c = f1 + (f2 - f1) * 6.0 * h;
  } else if((2.0 * h) < 1.0) {
    c = f2;
  } else if((3.0 * h) < 2.0) {
    c = f1 + (f2 - f1) * ((2.0/3.0) - h) * 6.0;
  } else {
    c = f1;
  }
  return c;
}
vec3 hsl2rgb(vec3 hsl){
  float h = hsl.x;
  float s = hsl.y;
  float l = hsl.z;
  if(s < 0.00001) {
    return vec3(l);
  }
  float f2;
  if(l < 0.5) f2 = l * (1.0 + s);
  else f2 = (l + s) - (s * l);
  float f1 = 2.0 * l - f2;
  float r = hue2rgb(f1, f2, h + 1.0/3.0);
  float g = hue2rgb(f1, f2, h);
  float b = hue2rgb(f1, f2, h - 1.0/3.0);
  return vec3(r,g,b);
}

vec3 colorFromPalette(float t, float index) {
  t = clamp(t, 0.0, 1.0);
  int i = int(mod(index, 4.0));
  if(i == 0) {
    return mix(vec3(0.15,0.45,0.8), vec3(0.95,0.76,0.22), t);
  }
  else if(i == 1) {
    return mix(vec3(0.0,0.7,0.7), vec3(1.0,0.5,0.0), t);
  }
  else if(i == 2) {
    return mix(vec3(0.8,0.15,0.55), vec3(0.2,0.35,0.95), t);
  }
  else {
    return mix(vec3(0.5,0.45,0.4), vec3(1.0,1.0,1.0), t);
  }
}

${fractalSnippet}

// Combine fractals more smartly
float smartWeight(vec3 c1, vec3 c2){
  float l1 = length(c1);
  float l2 = length(c2);
  return l1 / (l1 + l2 + 0.00001);
}

void main(){
  vec2 uv = (gl_FragCoord.xy - 0.5 * u_resolution) / min(u_resolution.x, u_resolution.y);
  uv -= (u_pan / min(u_resolution.x, u_resolution.y));
  uv *= u_zoom;

  ${coordTransforms}

  vec3 fcol = fractalSelector(uv, u_fractalMode);
  vec3 fcol2 = fractalSelector(uv, u_fractalMode2);
  float w = smartWeight(fcol, fcol2);
  vec3 blendedFractal = mix(fcol, fcol2, w);

  float fractalVal = length(blendedFractal);
  vec3 finalColor = colorFromPalette(fractalVal, u_paletteIndex);

  //POSTPROCESS_PLACEHOLDER

  // Stroke detection
  float edgeSum = 0.0;
  vec2 offX = vec2(1.0/u_resolution.x, 0.0);
  vec2 offY = vec2(0.0, 1.0/u_resolution.y);
  vec3 fUp1 = fractalSelector(uv + offY, u_fractalMode);
  vec3 fRight1 = fractalSelector(uv + offX, u_fractalMode);
  edgeSum += length(fcol - fUp1) + length(fcol - fRight1);
  vec3 fUp2 = fractalSelector(uv + offY, u_fractalMode2);
  vec3 fRight2 = fractalSelector(uv + offX, u_fractalMode2);
  edgeSum += length(fcol2 - fUp2) + length(fcol2 - fRight2);
  float strokeFactor = clamp(edgeSum * 4.0, 0.0, 1.0);
  finalColor = mix(finalColor, vec3(0.0), strokeFactor);

  gl_FragColor = vec4(finalColor, 1.0);
}
`;
}

function buildCoordTransformSnippet(){
  let transformCount = floor(random(1,5));
  let snippet = "vec2 coord = uv;\nuv = coord;\n";
  let possible = ["swirl","kaleido","moebius","invert"];
  for(let i=0; i<transformCount; i++){
    let choice = possible[floor(random(possible.length))];
    if(choice==="swirl"){
      let amt = nf(random(-2.0,2.0),1,3);
      snippet += `uv = swirlCoord(uv, float(${amt}));\n`;
    } else if(choice==="kaleido"){
      let seg = nf(random(3.0,10.0),1,3);
      snippet += `uv = kaleidoCoord(uv, float(${seg}));\n`;
    } else if(choice==="moebius"){
      let a = nf(random(-1.0,1.0),1,3);
      snippet += `uv = moebiusCoord(uv, float(${a}));\n`;
    } else if(choice==="invert"){
      snippet += `uv = invertCoord(uv);\n`;
    }
  }
  return snippet;
}

function buildExpression(nodesLeft, depth){
  if(nodesLeft < 1 || depth > MAX_DEPTH) {
    return randomLeaf();
  }
  if(random() < 0.3 && depth>0) {
    return randomLeaf();
  }
  var choice = randomOp();
  if(choice=="sin"||choice=="cos"||choice=="tan"||choice=="abs"||
     choice=="sqrt"||choice=="log"){
    let sub = buildExpression(nodesLeft-1, depth+1);
    if(choice=="sqrt"){
      return "sqrt(max(0.0, " + sub + "))";
    } else if(choice=="log"){
      return "log(abs(" + sub + ") + 0.0001)";
    } else {
      return choice + "(" + sub + ")";
    }
  }
  else if(choice=="mix"){
    var a = buildExpression(nodesLeft-1, depth+1);
    let b = buildExpression(nodesLeft-1, depth+1);
    let t = nf(random(0.0,1.0),1,3);
    return "mix(" + a + "," + b + "," + t + ")";
  }
  else if(choice=="min"||choice=="max"){
    var a = buildExpression(nodesLeft-1, depth+1);
    var b = buildExpression(nodesLeft-1, depth+1);
    return choice + "(" + a + "," + b + ")";
  }
  else if(choice=="+"||choice=="-"||choice=="*"||choice=="/"){
    var a = buildExpression(nodesLeft-1, depth+1);
    var b = buildExpression(nodesLeft-1, depth+1);
    if(choice=="/"){
      return "(safeDiv((" + a + "),(" + b + ")))";
    } else {
      return "(" + a + ")" + choice + "(" + b + ")";
    }
  }
  else if(choice=="fold01"){
    var sub = buildExpression(nodesLeft-1, depth+1);
    return "fold01(" + sub + ")";
  }
  else if(choice=="fractOp"){
    var sub = buildExpression(nodesLeft-1, depth+1);
    return "fract(" + sub + ")";
  }
  else if(choice=="noiseOp"){
    let xexp = buildExpression(nodesLeft-1, depth+1);
    let yexp = buildExpression(nodesLeft-1, depth+1);
    return "noise2D(vec2(" + xexp + "," + yexp + "))";
  }
  return randomLeaf();
}

function randomLeaf(){
  var r = floor(random(14));
  switch(r){
    case 0: return "uv.x";
    case 1: return "uv.y";
    case 2: return "u_time";
    case 3: return "u_params[0]";
    case 4: return "u_params[1]";
    case 5: return "u_params[2]";
    case 6: return "sqrt(uv.x*uv.x + uv.y*uv.y)";
    case 7: return "atan(uv.y,uv.x)";
    case 8: return "noise2D(vec2(uv.x,uv.y))";
    case 9: return "noise2D(vec2(u_time, uv.x - uv.y))";
    case 10: return "(length(uv)*sin(u_time))";
    case 11: return "(0.5 + 0.5*sin(uv.x*3.1415 + uv.y*3.1415))";
    case 12: return "(abs(sin(uv.x*5.0)*cos(uv.y*5.0)))";
    default:
      return nf(random(-1,1),1,3);
  }
}

function randomOp(){
  let ops = [
    "+","-","*","/",
    "sin","cos","tan","abs","sqrt","log",
    "mix","min","max",
    "fold01","fractOp","noiseOp"
  ];
  return ops[floor(random(ops.length))];
}

function setUniforms(s){
  s.setUniform("u_resolution", [windowWidth, windowHeight]);
  s.setUniform("u_zoom", zoomFactor);
  s.setUniform("u_pan", [panX, panY]);
  s.setUniform("u_time", millis()*0.001);
  paramArray = getCurrentParams();
  s.setUniform("u_params", paramArray);
  s.setUniform("u_fractalMode", fractalMode);
  s.setUniform("u_fractalMode2", fractalMode2);
  s.setUniform("u_paletteIndex", colorPaletteIndex);
}

function buildFractalSnippet(){
  return `
// Mandelbrot
vec3 mandelbrotColor(vec2 z){
  const int M_ITER = 128;
  vec2 c = z;
  vec2 w = vec2(0.0);
  int iCount = 0;
  for(int i=0; i<M_ITER; i++){
    if(dot(w,w) > 4.0){
      iCount = i;
      break;
    }
    w = vec2(w.x*w.x - w.y*w.y, 2.0*w.x*w.y) + c;
  }
  float v = float(iCount)/float(M_ITER);
  return vec3(v, v*v, sqrt(v));
}

// Julia
vec3 juliaColor(vec2 z){
  const int J_ITER = 128;
  vec2 c = vec2(0.355, 0.355);
  int iCount = 0;
  for(int i=0; i<J_ITER; i++){
    if(dot(z,z) > 4.0){
      iCount = i;
      break;
    }
    z = vec2(z.x*z.x - z.y*z.y, 2.0*z.x*z.y) + c;
  }
  float v = float(iCount)/float(J_ITER);
  return vec3(0.3 + 0.7*v, 0.2*v, v*v);
}

// Koch
vec3 kochSnowflakeColor(vec2 uv){
  float d = 0.0;
  float scale = 3.0;
  for(int i=0; i<5; i++){
    uv = abs(mod(uv*scale,2.0)-1.0);
    scale += 0.5;
    d += length(uv-0.5)*0.1;
  }
  d = fract(d*1.5);
  return vec3(d, 1.0-d, d*0.5);
}

// Sierpinski
float sierpinski(vec2 p) {
  for(int i=0; i<8; i++){
    if(p.x*0.5 > p.y) {
      return 0.0;
    }
    p *= 2.0;
  }
  return 1.0;
}
vec3 sierpinskiColor(vec2 uv){
  float v = sierpinski(uv*2.0+1.0);
  return vec3(v, v, v);
}

// Barnsley
vec3 barnsleyFernColor(vec2 z){
  float n = noise2D(z*10.0);
  return vec3(n, n*0.7, n*0.4);
}

// Cantor
float cantorDistance(float v){
  for(int i=0; i<12; i++){
    float r = mod(v*3.0,3.0);
    if(r>1.0 && r<2.0) return 0.0;
    v *= 3.0;
  }
  return 1.0;
}
vec3 cantorColor(vec2 uv){
  float val = cantorDistance((uv.x+1.0)*0.5);
  return vec3(val);
}

// Flame
vec3 flameColor(vec2 uv){
  float seed = uv.x * 12.9898 + uv.y * 78.233;
  const int ITER = 20;
  vec2 z = uv * 0.5;
  vec3 colorAccum = vec3(0.0);
  float alphaAccum = 0.0;
  for(int i = 0; i < ITER; i++){
    seed = fract(sin(seed) * 43758.5453);
    float r = seed * 4.0;
    if(r < 1.0){
      float r2 = dot(z,z) + 1e-6;
      z = z / r2;
      colorAccum += vec3(0.1, 0.4, 0.8);
    }
    else if(r < 2.0){
      float r2 = dot(z,z);
      float c = cos(r2);
      float s = sin(r2);
      z = vec2(c*z.x - s*z.y, s*z.x + c*z.y);
      colorAccum += vec3(0.8, 0.2, 0.4);
    }
    else if(r < 3.0){
      float r2 = dot(z,z) + 1e-6;
      z = vec2(
        (z.x - z.y)*(z.x + z.y)/r2,
        2.0*z.x*z.y / r2
      );
      colorAccum += vec3(0.2, 0.8, 0.3);
    }
    else {
      z = z * 0.7 + vec2(0.2, -0.2);
      colorAccum += vec3(1.0, 0.8, 0.0);
    }
    alphaAccum += 1.0;
  }
  vec3 finalColor = colorAccum / alphaAccum;
  finalColor = pow(finalColor, vec3(0.8));
  return finalColor;
}

// Lsystem
vec3 lsystemColor(vec2 uv){
  const int NUM_SEG = 6;
  vec4 lineSegments[6];
  lineSegments[0] = vec4(0.0, 0.0,  0.0, 0.5);
  lineSegments[1] = vec4(0.0, 0.5,  0.2, 0.7);
  lineSegments[2] = vec4(0.0, 0.5, -0.2, 0.7);
  lineSegments[3] = vec4(0.2, 0.7,  0.3, 1.0);
  lineSegments[4] = vec4(-0.2,0.7, -0.3, 1.0);
  lineSegments[5] = vec4(0.0, 0.5,  0.0, 1.0);

  float minDist = 1000.0;
  for(int i=0; i<NUM_SEG; i++){
    vec2 p1 = lineSegments[i].xy;
    vec2 p2 = lineSegments[i].zw;
    vec2 v = p2 - p1;
    vec2 w = uv - p1;
    float t = clamp(dot(w,v)/dot(v,v), 0.0, 1.0);
    vec2 projection = p1 + t*v;
    float distLine = length(uv - projection);
    if(distLine < minDist) minDist = distLine;
  }
  float threshold = 0.02;
  float lineMask = smoothstep(threshold, threshold*0.5, minDist);
  vec3 color = mix(vec3(0.1, 0.8, 0.2), vec3(0.0), lineMask);
  return color;
}

// Newton
vec3 newtonFractalColor(vec2 uv){
  const int MAX_ITER = 64;
  float power = 3.0;
  vec2 z = uv;
  for(int i=0; i<MAX_ITER; i++){
    float r2 = dot(z,z);
    if(r2 < 1e-9) break;
    vec2 fz = vec2(z.x*z.x*z.x - 3.0*z.x*z.y*z.y - 1.0,
                   3.0*z.x*z.x*z.y - z.y*z.y*z.y);
    vec2 dfz = vec2(3.0*(z.x*z.x - z.y*z.y),
                    3.0*(2.0*z.x*z.y));
    float denom = dfz.x*dfz.x + dfz.y*dfz.y + 1e-12;
    vec2 corr = vec2(
      (fz.x*dfz.x + fz.y*dfz.y)/denom,
      (fz.y*dfz.x - fz.x*dfz.y)/denom
    );
    z = z - corr;
  }
  vec2 root1 = vec2(1.0, 0.0);
  vec2 root2 = vec2(-0.5,  0.8660254037);
  vec2 root3 = vec2(-0.5, -0.8660254037);
  float d1 = length(z - root1);
  float d2 = length(z - root2);
  float d3 = length(z - root3);
  if(d1 < d2 && d1 < d3){
    return vec3(1.0, 0.3, 0.3);
  } else if(d2 < d1 && d2 < d3){
    return vec3(0.3, 1.0, 0.3);
  } else {
    return vec3(0.3, 0.3, 1.0);
  }
}

// Lorenz
vec3 lorenzColor(vec2 uv){
  float x=0.01, y=0.0, z=0.0;
  float dt=0.01;
  float sigma=10.0, rho=28.0, beta=8.0/3.0;
  float c=0.0;
  for(int i=0; i<100; i++){
    float dx = sigma*(y - x);
    float dy = x*(rho - z) - y;
    float dz = x*y - beta*z;
    x += dx*dt;
    y += dy*dt;
    z += dz*dt;
    if(abs(uv.x - x*0.02) < 0.005 && abs(uv.y - y*0.02) < 0.005) c += 1.0;
  }
  c = clamp(c,0.0,1.0);
  return vec3(c, c*0.5, c*0.8);
}

// Rössler
vec3 rosslerColor(vec2 uv){
  float x=0.01, y=0.0, z=0.0;
  float a=0.2, b=0.2, c=5.7;
  float dt=0.02;
  float col=0.0;
  for(int i=0; i<80; i++){
    float dx = -(y+z);
    float dy = x+a*y;
    float dz = b+z*(x-c);
    x += dx*dt; y += dy*dt; z += dz*dt;
    if(abs(uv.x - x*0.03) < 0.007 && abs(uv.y - y*0.03) < 0.007) col += 1.0;
  }
  return vec3(col, 0.5*col, col*0.3);
}

// Apollonian
vec3 apollonianColor(vec2 uv){
  float t=0.0;
  vec2 p = uv*2.0;
  for(int i=0; i<5; i++){
    float r = length(p) - 1.0;
    t += step(r,0.0);
    p *= 1.5;
  }
  return vec3(fract(t), fract(t*0.5), fract(t*0.7));
}

// Pythagoras
vec3 pythagorasTreeColor(vec2 uv){
  float col=0.0;
  vec2 p = uv;
  for(int i=0; i<5; i++){
    p = abs(p)*1.2 - 0.5;
    col += step(length(p), 0.5);
  }
  return vec3(col*0.2, col*0.6, col);
}

// Penrose
vec3 penroseColor(vec2 uv){
  float angles[5];
  angles[0] = 0.0;
  angles[1] = 72.0;
  angles[2] = 144.0;
  angles[3] = 216.0;
  angles[4] = 288.0;
  float n = 0.0;
  uv *= 2.0;
  for(int i = 0; i < 5; i++){
    float a = radians(angles[i]);
    float d = uv.x * cos(a) + uv.y * sin(a);
    n += cos(d * 1.61803);
  }
  float c = (n + 5.0) / (2.0 * 5.0);
  c = fract(c);
  return vec3(c, c * 0.7, 1.0 - c);
}

// Voronoi
float voronoi(vec2 x){
  vec2 n = floor(x);
  vec2 f = fract(x);
  float res = 1.0;
  for(int j=-1;j<=1;j++){
    for(int i=-1;i<=1;i++){
      vec2 g = vec2(float(i),float(j));
      vec2 o = hash2(n+g);
      vec2 r = g + o - f;
      float d = dot(r,r);
      res = min(res, d);
    }
  }
  return sqrt(res);
}
vec3 voronoiColor(vec2 uv){
  float v = voronoi(uv*4.0);
  return vec3(v, 1.0-v, v*0.5);
}

// Mandelbulb
vec3 mandelbulbColor(vec2 uv){
  const int MBULB_ITER = 30;
  vec2 z = uv;
  float power = 8.0;
  float r = length(z);
  float theta = atan(z.y, z.x);
  int iCount = 0;
  for(int i=0; i<MBULB_ITER; i++){
    r = pow(r, power);
    theta *= power;
    z = vec2(r*cos(theta), r*sin(theta)) + uv;
    if(length(z) > 2.0){
      iCount = i;
      break;
    }
    r = length(z);
    theta = atan(z.y, z.x);
  }
  float val = float(iCount)/float(MBULB_ITER);
  return vec3(val, val*0.5, val*0.2);
}

// Mandelbox
vec3 mandelboxColor(vec2 uv){
  const int MBOX_ITER = 24;
  vec2 z = uv;
  float scale = 1.5;
  int iCount = 0;
  for(int i=0; i<MBOX_ITER; i++){
    if(z.x > 1.0) z.x = 2.0 - z.x;
    else if(z.x < -1.0) z.x = -2.0 - z.x;
    if(z.y > 1.0) z.y = 2.0 - z.y;
    else if(z.y < -1.0) z.y = -2.0 - z.y;
    z *= scale;
    z += uv;
    if(length(z) > 2.0){
      iCount = i;
      break;
    }
  }
  float val = float(iCount)/float(MBOX_ITER);
  return vec3(val*0.6, val, val*0.3);
}

// Duffing
vec3 duffingColor(vec2 uv){
  float x = 0.1;
  float y = 0.0;
  float a = 2.75;
  float b = 0.2;
  float dt = 0.02;
  float c = 0.0;
  for(int i=0; i<100; i++){
    float dx = y;
    float dy = -b*y - a*x - x*x*x;
    x += dx * dt;
    y += dy * dt;
    if(abs(uv.x - x*0.1) < 0.01 && abs(uv.y - y*0.1) < 0.01){
      c += 1.0;
    }
  }
  c = clamp(c, 0.0, 1.0);
  return vec3(c, c*0.7, c*0.4);
}

// selector
vec3 fractalSelector(vec2 uv, float mode){
  int m = int(mod(mode, 18.0));
  if(m == 0) return mandelbrotColor(uv);
  else if(m == 1) return juliaColor(uv);
