  else if(m == 7) return lsystemColor(uv);
  else if(m == 8) return newtonFractalColor(uv);
  else if(m == 9) return lorenzColor(uv);
  else if(m == 10) return rosslerColor(uv);
  else if(m == 11) return apollonianColor(uv);
  else if(m == 12) return pythagorasTreeColor(uv);
  else if(m == 13) return penroseColor(uv);
  else if(m == 14) return voronoiColor(uv);
  else if(m == 15) return mandelbulbColor(uv);
  else if(m == 16) return mandelboxColor(uv);
  else if(m == 17) return duffingColor(uv);
  else {
    float ssm = floor(fract(uv.x + uv.y +  u_time) * 9.0);
